INSERT INTO announcements (title, message, priority, publish_date, expiry_date) VALUES
  ('Welcome to KaaryaSetu HRMS!', 'We are excited to launch our central HR platform. All 200+ employee records, payroll, leave balances, and attendance tracking are now live.', 'important', CURRENT_DATE - 5, CURRENT_DATE + 30),
  ('Annual Performance Appraisals 2026', 'Q3 performance review cycles have officially begun across Engineering, HR, Finance, Marketing, and Sales departments.', 'urgent', CURRENT_DATE, CURRENT_DATE + 15);
